contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 supply, uint256 burnAmount) public {
        c = new C(supply, "n", "s");
        // after deployment msg.sender (this contract) owns full supply
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        bool ok;
        if (burnAmount <= balBefore) {
            ok = c.burn(burnAmount);
            uint256 supplyAfter = c.totalSupply();
            uint256 balAfter = c.balanceOf(address(this));
            assert(ok && supplyBefore == supplyAfter + burnAmount && balBefore == balAfter + burnAmount);
        } else {
            try c.burn(burnAmount) { ok = true; } catch { ok = false; }
            assert(!ok && c.totalSupply() == supplyBefore && c.balanceOf(address(this)) == balBefore);
        }
    }
    receive() external payable {}
}

