contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 seedSupply, uint256 value) public {
        require(seedSupply > 0);
        require(value > 0);
        require(seedSupply >= value);
        c.mintToken(address(this), seedSupply);
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        require(balBefore >= value);
        bool reverted;
        try c.burn(value) { reverted = false; } catch { reverted = true; }
        uint256 supplyAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));
        assert((!reverted && supplyBefore - supplyAfter == value && balBefore - balAfter == value)
            || (reverted && balBefore < value));
    }
    receive() external payable {}
}

